import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = Integer.parseInt(sc.nextLine().trim());
        int emailCount = 0;
        int smsCount = 0;
        for(int i = 0; i < n; i++) {
            String line = sc.nextLine().trim();
            int space = line.indexOf(' ');
            String kind = line.substring(0, space);
            String message = line.substring(space + 1);
            Notification note;
            if(kind.equals("email")) {
                note = new EmailNotification();
                emailCount++;
            } else {
                note = new SMSNotification();
                smsCount++;
            }
            note.send(message);
        }
        System.out.println("Email total: " + emailCount);
        System.out.println("SMS total: " + smsCount);
    }
}

abstract class Notification {
    abstract void send(String message);
}

class EmailNotification extends Notification {
    void send(String message) {
        System.out.println("EMAIL: " + message);
    }
}

class SMSNotification extends Notification {
    void send(String message) {
        System.out.println("SMS: " + message);
    }
}

